const std = @import("std");

pub fn main() !void {
    var a: u32 = 0;
    var b: u32 = 1;

    for (0..10) |_| {
        std.debug.print("{} ", .{a});
        const next = a + b;
        a = b;
        b = next;
    }
    std.debug.print("\n", .{});
}

